<?php $s=$garden_summary;$a=$garden_activity;$p=$summary_permissions; ?>
<section class="garden-panel"><div class="garden-panel-heading"><div><span class="garden-kicker">THE BUSINESS, THE NURSERY & THE FIELD</span><h2><?= $summary_from===$summary_to ? 'Your day in Garden' : 'Garden activity summary'; ?></h2><p class="garden-muted"><?= htmlspecialchars($summary_from.' → '.$summary_to); ?> · All branches</p></div></div><form method="get" action="<?= base_url('garden/daily_summary'); ?>"><div class="garden-grid"><label>From<input type="date" name="date_from" value="<?= htmlspecialchars($summary_from); ?>" required></label><label>To<input type="date" name="date_to" value="<?= htmlspecialchars($summary_to); ?>" required></label></div><?php if($this->input->get('screen')==='mobile'): ?><input type="hidden" name="screen" value="mobile"><?php endif; ?><button class="garden-button">Show activity</button></form></section>
<section class="garden-panel"><span class="garden-kicker">SALES & MONEY</span><h2>Trading performance</h2><div class="garden-grid"><?php $cards=[];if($p['sales_view']){$cards[]=['Invoiced sales',$s['sales']['total'],'sales'];$cards[]=['Cash collected',$s['sales']['cash_expected'],'reports/sales_payments'];$cards[]=['Bank / POS collected',$s['sales']['bank_pos_expected']??0,'reports/sales_payments'];}if($p['expense_view'])$cards[]=['Recorded expenses',$s['expenses']['total'],'expense'];if($p['profit_report'])$cards[]=['Recorded gross profit',$s['profit']['gross_profit'],'reports/profit_loss'];foreach($cards as $card): ?><a class="garden-card" href="<?= base_url($card[2]); ?>"><small><?= $card[0]; ?></small><h2><?= store_number_format($card[1]); ?></h2></a><?php endforeach; ?></div><p class="garden-muted">Amounts use the existing sales, payment and finance sources for the selected period. Batch cost allocations below are separate and must not be added to recorded expenses.</p><?php if($p['sales_view'] && $p['customers_view']): ?><p>Current customer balances · all dates: <strong><?= store_number_format($s['outstanding_debts']['total']); ?></strong></p><?php endif; ?><?php if(!$cards): ?><p>No financial figures are available for your role.</p><?php endif; ?></section>
<?php if(isset($a['plant_losses'])): ?><section class="garden-panel"><span class="garden-kicker">NURSERY STOCK</span><h2>Finished plant losses</h2><div class="garden-grid"><div class="garden-card"><small>Units recorded lost</small><h2><?= format_qty($a['plant_losses']->units); ?></h2></div><div class="garden-card"><small>Recorded stock cost</small><h2><?= store_number_format($a['plant_losses']->cost); ?></h2></div></div><a href="<?= base_url('garden/nursery'); ?>">Review plant loss records →</a><p class="garden-muted">Finished stock losses are separate from unfinished growing-batch losses.</p></section><?php endif; ?>
<?php if(isset($a['production'])): ?><section class="garden-panel"><div class="garden-panel-heading"><div><span class="garden-kicker">GROWING & ASSEMBLY</span><h2>Production activity</h2></div><a href="<?= base_url('garden/production'); ?>">Open production board →</a></div><div class="garden-grid"><?php $labels=['start'=>'Batches started','complete'=>'Batches completed','loss'=>'Unfinished units lost','material'=>'Material cost issued','labour'=>'Labour cost allocated','other'=>'Other costs allocated'];foreach($a['production_activity'] as $row):if(!isset($labels[$row->kind]))continue; ?><div class="garden-card"><small><?= $labels[$row->kind]; ?></small><h2><?= in_array($row->kind,['material','labour','other'],true)?store_number_format($row->cost):($row->kind==='loss'?format_qty($row->quantity):(int)$row->entries); ?></h2></div><?php endforeach; ?></div><h3>Completed output in this period</h3><div class="garden-summary-list"><?php foreach($a['production'] as $b): ?><a href="<?= base_url('garden/production_batch/'.(int)$b->batch_id); ?>"><span><strong><?= htmlspecialchars($b->batch_name); ?></strong><br><?= htmlspecialchars($b->item_name); ?> · <?= (int)$b->saleable_qty; ?> saleable units</span><span><?= store_number_format($b->completed_cost); ?> total<br><?= $b->unit_cost!==null?store_number_format($b->unit_cost).' / unit':'No saleable output'; ?></span></a><?php endforeach; ?></div><?php if(!$a['production']): ?><p class="garden-muted">No batches completed in this period.</p><?php endif; ?><p class="garden-muted">Completion costs include all inputs allocated over each batch’s lifetime. Activity cards include only entries made in this period. Up to 100 completed batches are listed.</p></section><?php endif; ?>
<?php if(isset($a['projects_created'])): ?><section class="garden-panel"><span class="garden-kicker">PROJECTS & FIELD WORK</span><h2>Landscaping progress</h2><div class="garden-grid"><div class="garden-card"><small>New projects</small><h2><?= (int)$a['projects_created']; ?></h2></div><div class="garden-card"><small>Projects marked complete</small><h2><?= (int)$a['projects_completed']; ?></h2></div><div class="garden-card"><small>Site assessments recorded</small><h2><?= (int)($a['inspections']??0); ?></h2></div></div><a href="<?= base_url('garden/projects'); ?>">Open project board →</a><h3>Scheduled jobs & visits</h3><p class="garden-muted">Scheduled within this period, showing their current status. Up to 100 visits.</p><div class="garden-summary-list"><?php foreach($a['visits'] as $v): ?><a href="<?= base_url('garden/work#job-'.(int)$v->id); ?>"><span><?= htmlspecialchars($v->title); ?><br><small><?= htmlspecialchars($v->customer_name ?? ''); ?></small></span><span><?= htmlspecialchars($v->scheduled_date); ?><br><?= htmlspecialchars(ucwords(str_replace('_',' ',$v->status))); ?></span></a><?php endforeach; ?></div><?php if(!$a['visits']): ?><p>No scheduled visits in this period.</p><?php endif; ?></section><?php endif; ?>
